param([Parameter(Mandatory)][ValidateSet('BASELINE','REMEDIATION')][string]$Condition)
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'experiment-1-23-collector-lifecycle.ps1')
$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;$project="doeng-exp123-probe-$($Condition.ToLowerInvariant())";$app='doeng-flux-exp119-fresh-first-20260803:latest';$mock='doeng-exp119-mock-frozen-20260803:latest';$appId='sha256:c2878d2847f80f3396a5cee5f02f1ec1ca3f7c14ceb8f49ea610d6e5fb6d9168';$mockId='sha256:2492f942c3931aa607293cf3da940e0e5aac0cfae91cbfe0ea88a893f0829ac1'
$tag=if($Condition-eq'BASELINE'){'FIFO'}else{'LIFO'};$idle=if($Condition-eq'BASELINE'){0}else{3000};$evict=if($Condition-eq'BASELINE'){0}else{1000};$files=@('backend\docker-compose.experiment.yaml','backend\docker-compose.app-instance-t3-medium.yaml','backend\docker-compose.mock-headroom-4cpu.yaml','backend\docker-compose.http-pool-400.yaml','backend\docker-compose.mock-memory-headroom.yaml','backend\docker-compose.experiment-1-12-connection-attribution.yaml','backend\docker-compose.experiment-1-19-fresh-first-lifecycle.yaml');$compose=@();foreach($f in $files){$compose+=@('-f',(Join-Path $root $f))};$result=Join-Path $root 'backend\experiments\results\experiment-1-23\probe';$dir=Join-Path $result $Condition;$staging=Join-Path $root "backend\experiments\results\experiment-1-23\collector-staging\PROBE-$Condition";New-Item -ItemType Directory -Force $dir,$staging|Out-Null
if((docker image inspect --format '{{.Id}}' $app).Trim()-ne$appId -or(docker image inspect --format '{{.Id}}' $mock).Trim()-ne$mockId){throw 'FROZEN_IMAGE_MISMATCH'};$old=@{};foreach($e in @{'DOENG_EXP119_APP_IMAGE'=$app;'DOENG_EXP119_MOCK_IMAGE'=$mock;'DOENG_EXTERNAL_LEASING_STRATEGY'=$tag;'DOENG_EXTERNAL_MAX_IDLE_TIME_MS'=$idle;'DOENG_EXTERNAL_EVICTION_INTERVAL_MS'=$evict}.GetEnumerator()){$old[$e.Key]=[Environment]::GetEnvironmentVariable($e.Key,'Process');[Environment]::SetEnvironmentVariable($e.Key,[string]$e.Value,'Process')};$collector=$null
try {docker compose -p $project @compose up -d --force-recreate --no-build mariadb experiment-mock flux-corrected;if($LASTEXITCODE){throw 'FRESH_RECREATE_FAILED'};$health=$false;for($i=0;$i-lt30;$i++){try{if((Invoke-WebRequest http://127.0.0.1:9001/actuator/health -UseBasicParsing -TimeoutSec 2).StatusCode-eq200){$health=$true;break}}catch{};Start-Sleep -Seconds 1};if(-not$health){throw 'HEALTH_FAILED'};$signal=Join-Path $staging 'STOP-COLLECTOR';$out=Join-Path $staging 'pool-metrics.jsonl';$summary=Join-Path $staging 'pool-metrics.jsonl.summary.json';$started=(Get-Date).ToUniversalTime().ToString('o');$collector=Start-Process powershell.exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',(Join-Path $PSScriptRoot 'collect-diagnostic-pool-until-stop.ps1'),'-ManagementUrl','http://127.0.0.1:9001','-OutputPath',$out,'-SummaryPath',$summary,'-StopSignalPath',$signal,'-IntervalMilliseconds','1000','-MaxDurationSeconds','300') -WindowStyle Hidden -PassThru;$ready=Wait-Exp123CollectorReady $collector $out 10;New-Item -ItemType File -Path ($signal+'.tmp')|Out-Null;Move-Item -Force ($signal+'.tmp') $signal;if(-not$collector.WaitForExit(10000)){throw 'COLLECTOR_STOP_TIMEOUT'};$summaryObj=Get-Content $summary -Raw|ConvertFrom-Json;if($summaryObj.collectorStatus-ne'COLLECTOR_STOPPED_BY_SIGNAL'-or$summaryObj.stopSignalObserved-ne$true-or[int]$summaryObj.failures-ne0-or[int]$collector.ExitCode-ne0){throw 'COLLECTOR_SUMMARY_INVALID'};[ordered]@{condition=$Condition;status='CORE_BOUND_COLLECTOR_PROBE_READY';composeFiles=$files;applicationImageId=$appId;mockImageId=$mockId;policy=@{leasingStrategy=$tag;maxIdleTimeMs=$idle;evictionIntervalMs=$evict};collectorStartedAt=$started;collectorReady=$ready;collector=$summaryObj;warmupInvocations=0;k6Invocations=0;coreInvocations=0}|ConvertTo-Json -Depth 12|Set-Content (Join-Path $dir 'probe-summary.json') -Encoding UTF8;Write-Output 'CORE_BOUND_COLLECTOR_PROBE_READY'}finally{if($null-ne$collector -and -not$collector.HasExited){$collector.Kill()};docker compose -p $project @compose down --remove-orphans|Out-Null;foreach($e in $old.GetEnumerator()){[Environment]::SetEnvironmentVariable($e.Key,$e.Value,'Process')}}
